// Independent CPU PyTorch 2.4.1 capture of canonical HF LFM3 ac2586a3, not generated by either production path.
// The fixture records provenance plus exact inverse-frequency/phase bits; CPU trig implementations differ by <= 1 ULP.
const test = require('node:test');
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const vm = require('node:vm');
const R = require('../../extension/ai/local/reference.js');
const fixture = require('../fixtures/ai/hf-rope-f32-cpu.json');
const positions = [8191, 8192, 32767, 32768, 32777, 32792, 32848, 131071, 131072];
const bits = (x) => new Uint32Array(Float32Array.of(x).buffer)[0];
const value = (x) => new Float32Array(Uint32Array.of(x).buffer)[0];
const ordered = (u) => u & 0x80000000 ? 0x80000000 - (u & 0x7fffffff) : 0x80000000 + u;
const trig = (actual, expectedBits, label) => {
  const distance = Math.abs(ordered(bits(actual)) - ordered(expectedBits));
  assert.ok(distance <= 1, `${label}: ${actual} vs ${value(expectedBits)} (${distance} ULP)`);
};
const factors = (layer) => layer.activePairs === layer.headDim / 2 ? null
  : Float32Array.from({ length: layer.headDim / 2 }, (_, i) => i < layer.activePairs ? 1 : 1e30);

// Observe the actual public calls' trig arguments, rather than reproducing the phase formula in the regression.
const observed = () => {
  const phases = [], math = Object.create(Math);
  math.cos = (theta) => { phases.push(theta); return Math.cos(theta); };
  const context = vm.createContext({ Math: math });
  for (const file of ['reference.js', 'engine.js']) vm.runInContext(fs.readFileSync(path.join(__dirname, '../../extension/ai/local', file), 'utf8'), context);
  return { phases, engine: context.GZ_AI_ENGINE, reference: context.GZ_AI_REFERENCE };
};
const phase = (actual, expectedBits, label) => assert.equal(actual, value(expectedBits), `${label}: exact captured f32 phase`);

test('the external oracle covers both LFM3 bases, the context boundaries and the three mismatch positions', () => {
  assert.equal(fixture.sourceSha256, 'e8cd5254ea99ce6bd731b57b10908c2e8b5010ce8315341f895a38484885eeab');
  assert.equal(fixture.device, 'cpu');
  assert.match(fixture.torchVersion, /^2\.4\.1/);
  assert.deepEqual(fixture.layers.map((l) => [l.base, l.headDim, l.activePairs]), [[1e6, 128, 32], [1e4, 128, 64]]);
  for (const layer of fixture.layers) assert.deepEqual(layer.positions.map((p) => p.position), positions);
});

for (const layer of fixture.layers) {
  test(`engine RoPE tables match independent HF f32 phases and trig: ${layer.layerType}`, () => {
    const { engine, phases } = observed(), n = layer.headDim;
    for (const row of layer.positions) {
      phases.length = 0;
      const table = engine.ropeTable(row.position, 1, n, layer.base, factors(layer));
      assert.equal(phases.length, n / 2);
      for (let i = 0; i < n / 2; i++) {
        const label = `${layer.layerType} position ${row.position} pair ${i}`;
        trig(table[2 * i], row.cosBits[i], `${label} cos`);
        trig(table[2 * i + 1], row.sinBits[i], `${label} sin`);
        phase(phases[i], row.phaseBits[i], label);
      }
    }
  });

  test(`CPU reference rotates both basis vectors against the independent HF capture: ${layer.layerType}`, () => {
    const { reference, phases } = observed(), n = layer.headDim, half = n / 2, heads = 2;
    const x = new Float32Array(positions.length * heads * n);
    // Each independent 2-D rotation gets (1, 0) in head 0, (0, 1) in head 1.
    for (let t = 0; t < positions.length; t++) for (let i = 0; i < half; i++) {
      x[t * heads * n + i] = 1;
      x[(t * heads + 1) * n + i + half] = 1;
    }
    reference._ops.rope(x, positions.length, heads, n, positions, n, layer.base, factors(layer));
    assert.equal(phases.length, positions.length * half);
    layer.positions.forEach((row, t) => {
      for (let i = 0; i < half; i++) {
        const o = t * heads * n, label = `${layer.layerType} position ${row.position} pair ${i}`;
        trig(x[o + i], row.cosBits[i], `${label} basis 0 cos`);
        trig(x[o + i + half], row.sinBits[i], `${label} basis 0 sin`);
        trig(x[o + n + i], (row.sinBits[i] ^ 0x80000000) >>> 0, `${label} basis 1 -sin`);
        trig(x[o + n + i + half], row.cosBits[i], `${label} basis 1 cos`);
        phase(phases[t * half + i], row.phaseBits[i], label);
      }
    });
  });
}

test('inverse-frequency bits match every captured HF pair, including the exact zero tail', () => {
  for (const layer of fixture.layers) {
    const freq = R._ops.ropeFreqs(layer.headDim, layer.base, factors(layer));
    assert.deepEqual([...new Uint32Array(freq.buffer, freq.byteOffset, freq.length)], layer.invFreqBits);
  }
});

test('ordinary factor scaling and partial head dimensions remain supported; only the exact converter sentinel is zero', () => {
  const { engine, reference } = observed(), n = 8, hd = 12, base = 1e4;
  const scaled = engine.ropeTable(16, 1, n, base, Float32Array.of(2, 2, 2, 2));
  assert.deepEqual([...scaled], [...engine.ropeTable(8, 1, n, base, null)]);
  const x = Float32Array.of(1, 1, 1, 1, 0, 0, 0, 0, 7, 8, 9, 10);
  reference._ops.rope(x, 1, 1, hd, [16], n, base, Float32Array.of(2, 2, 2, 2));
  for (let i = 0; i < n / 2; i++) { assert.equal(x[i], scaled[2 * i]); assert.equal(x[i + n / 2], scaled[2 * i + 1]); }
  assert.deepEqual([...x.slice(n)], [7, 8, 9, 10]);
  const sentinel = bits(Math.fround(1e30)), ff = Float32Array.of(value(sentinel - 1), value(sentinel), value(sentinel + 1), 3);
  const freq = R._ops.ropeFreqs(n, base, ff), table = engine.ropeTable(8192, 1, n, base, ff);
  assert.equal(freq[1], 0);
  assert.equal(table[2], 1); assert.equal(table[3], 0);
  for (const i of [0, 2, 3]) {
    assert.ok(freq[i] > 0, `factor ${ff[i]} retains its inverse frequency`);
    assert.equal(freq[i], Math.fround(R._ops.ropeFreqs(n, base, null)[i] / ff[i]), 'ordinary factors scale frequency');
    assert.notEqual(table[2 * i + 1], 0, `factor ${ff[i]} still rotates`);
  }
});
